import React from 'react';
import { motion } from 'framer-motion';

/* Fallback if backend doesn't return ensemble yet */
const FALLBACK = {
  direction: 'N/A',
  probability: 0.5,
  signals: {
    lstm_direction: { value: 0.5, weight: 0.50 },
    rsi:            { value: 0.5, weight: 0.20 },
    macd_cross:     { value: 0.5, weight: 0.20 },
    ma_crossover:   { value: 0.5, weight: 0.10 },
  }
};

const SIG_LABELS = {
  lstm_direction: 'LSTM Dir. Head',
  rsi:            'RSI Signal',
  macd_cross:     'MACD Cross',
  ma_crossover:   'MA Cross',
};

const EnsemblePanel = ({ ensemble }) => {
  const ens = ensemble || FALLBACK;
  const sigs = ens.signals || FALLBACK.signals;
  const isBull = (ens.direction || '').includes('UP') || ens.probability >= 0.5;

  return (
    <motion.div
      className="card ensemble-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.1 }}
    >
      <div className="card-title">
        <div className="card-ico ico-g">🎯</div>
        <span className="card-title-text">Direction Ensemble</span>
      </div>

      <div className="signal-list">
        {Object.entries(sigs).map(([key, sig], i) => {
          const bull = sig.value >= 0.5;
          const pct  = sig.value * 100;
          return (
            <motion.div
              key={key}
              className="signal-row"
              initial={{ opacity: 0, x: -12 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.15 + i * 0.07 }}
            >
              <span className="sig-name">{SIG_LABELS[key] || key}</span>
              <div className="sig-bar">
                <motion.div
                  className={`sig-fill ${bull ? 'bull' : 'bear'}`}
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.9, delay: 0.2 + i * 0.07 }}
                />
              </div>
              <span className="sig-val" style={{ color: bull ? 'var(--green)' : 'var(--red)' }}>
                {(sig.value * 100).toFixed(0)}%
              </span>
              <span className="sig-wt">×{sig.weight}</span>
            </motion.div>
          );
        })}
      </div>

      <div className={`ens-result ${isBull ? 'bull' : 'bear'}`}>
        <span className={`ens-dir ${isBull ? 'bull' : 'bear'}`}>
          {isBull ? '↑ BULLISH' : '↓ BEARISH'}
        </span>
        <span className="ens-prob">
          Composite: {((ens.probability || 0.5) * 100).toFixed(0)}%
        </span>
      </div>
    </motion.div>
  );
};

export default EnsemblePanel;
